import sys
import math


def main():
    text = sys.stdin.read()
    lines = text.split('\n')
    groups = {}
    get = groups.get
    for ln in lines[1:]:
        if not ln:
            continue
        parts = ln.split(',')
        if len(parts) < 3:
            continue
        c = parts[1]
        v = float(parts[2])
        lst = get(c)
        if lst is None:
            groups[c] = [v]
        else:
            lst.append(v)
    out = []
    for c in sorted(groups):
        out.append('%s,%.2f' % (c, math.fsum(groups[c])))
    if out:
        sys.stdout.write('\n'.join(out) + '\n')


main()

import sys


def main():
    f = sys.stdin.read().split()
    sums = {}
    get = sums.get
    for ln in f[1:]:
        c, _, v = ln.split(',')
        sums[c] = get(c, 0.0) + float(v)
    out = ['%s,%.2f' % (c, sums[c]) for c in sorted(sums) if c]
    if out:
        sys.stdout.write('\n'.join(out) + '\n')


main()

import sys


def main():
    data = sys.stdin.buffer.read().split(b'\n')
    sums = {}
    get = sums.get
    for ln in data[1:]:
        if not ln:
            continue
        c, _, v = ln.partition(b',')[0], 0, ln.rpartition(b',')[2]
        c = ln.split(b',', 2)[1]
        sums[c] = get(c, 0.0) + float(v)
    out = [b'%s,%.2f' % (c, sums[c]) for c in sorted(sums) if c]
    if out:
        sys.stdout.buffer.write(b'\n'.join(out) + b'\n')


main()

import sys


def main():
    f = sys.stdin.read().replace('\n', ',').split(',')
    sums = {}
    for c, v in zip(f[4::3], map(float, f[5::3])):
        sums[c] = sums.get(c, 0.0) + v
    out = ['%s,%.2f' % (c, sums[c]) for c in sorted(sums) if c]
